// Host test for lib/access_decision (no hardware, no crypto).
// Card bytes are generated by examples/hospital/check_access.py --card <id>,
// so firmware and example are checked against each other.
//
// Run from firmware/test/host:
//   g++ -std=c++17 -Wall -Wextra -I../../lib/access_decision/src test_access_decision.cpp ../../lib/access_decision/src/*.cpp -o t && ./t

#include <cstdio>
#include <vector>

#include "access_decision.h"
#include "clock.h"

using namespace opencylinder;

static int failures = 0;
#define CHECK(cond)                                                        \
  do {                                                                     \
    if (!(cond)) {                                                         \
      std::printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);          \
      ++failures;                                                          \
    }                                                                      \
  } while (0)

struct Card {
  std::vector<uint8_t> file0, file1;
};

// Bench lock = example door 4 "Ward 1 - ward door", zones 3 + 4, blacklist 2003.
static const uint16_t kZones[] = {3, 4};
static const uint32_t kBlacklist[] = {2003};
static const LockConfig kLock{4, kZones, 2, kBlacklist, 1};

static Result run(const Card& c, bool timeKnown, uint32_t now) {
  CardHeader h;
  CHECK(parseHeader(c.file0.data(), c.file0.size(), h));
  std::vector<AccessEntry> e;
  CHECK(parseEntries(c.file1.data(), c.file1.size(), h.entryCount, e));
  return decide(h, e, kLock, timeKnown, now);
}

int main() {
  const Card sara{{0x01, 0x03, 0, 0, 0xD1, 0x07, 0, 0, 0, 0, 0, 0, 0x80, 0xF2, 0x03, 0x6B},
                  {0x02, 0x01, 0, 0, 0x02, 0x04, 0, 0, 0x02, 0x07, 0, 0}};
  const Card max{{0x01, 0x03, 0, 0, 0xD2, 0x07, 0, 0, 0, 0, 0, 0, 0x80, 0xF2, 0x03, 0x6B},
                 {0x02, 0x01, 0, 0, 0x02, 0x05, 0, 0, 0x02, 0x07, 0, 0}};
  const Card eva{{0x01, 0x03, 0, 0, 0xD3, 0x07, 0, 0, 0, 0, 0, 0, 0x80, 0xF2, 0x03, 0x6B},
                 {0x02, 0x01, 0, 0, 0x02, 0x04, 0, 0, 0x02, 0x07, 0, 0}};
  const Card olga{{0x01, 0x03, 0, 0, 0xA1, 0x0F, 0, 0, 0x60, 0x77, 0xAD, 0x6B, 0x80, 0xF2, 0x03, 0x6B},
                  {0x02, 0x01, 0, 0x02, 0x02, 0x03, 0, 0x02, 0x02, 0x07, 0, 0x02}};
  const Card ben{{0x01, 0x03, 0, 0, 0xA2, 0x0F, 0, 0, 0xF0, 0x72, 0xE6, 0x6A, 0x80, 0xF2, 0x03, 0x6B},
                 {0x02, 0x01, 0, 0x02, 0x02, 0x03, 0, 0x02, 0x02, 0x07, 0, 0x02}};
  const Card koch{{0x01, 0x07, 0, 0, 0xE9, 0x03, 0, 0, 0, 0, 0, 0, 0x80, 0xF2, 0x03, 0x6B},
                  {0x02, 0x01, 0, 0, 0x02, 0x02, 0, 0, 0x02, 0x03, 0, 0, 0x02, 0x06, 0, 0,
                   0x02, 0x07, 0, 0, 0x02, 0x0A, 0, 0, 0x01, 0x0D, 0, 0}};

  const uint32_t now = 1795510800;  // 2026-11-24 10:00 Europe/Berlin (09:00 UTC)

  // Header parse
  CardHeader h;
  CHECK(parseHeader(sara.file0.data(), 16, h));
  CHECK(h.formatVersion == 1 && h.entryCount == 3 && h.credentialId == 2001);
  CHECK(h.validUntil == 0 && h.issuedAt == 0x6B03F280u);
  CHECK(!parseHeader(sara.file0.data(), 15, h));

  // Same results as check_access.py --door 4
  Result r = run(sara, true, now);
  CHECK(r.decision == Decision::Open && r.matched.type == kEntryZone && r.matched.targetId == 4);
  CHECK(run(max, true, now).decision == Decision::DenyNoRight);
  CHECK(run(eva, true, now).decision == Decision::DenyBlacklisted);
  CHECK(run(ben, true, now).decision == Decision::DenyExpired);
  r = run(koch, true, now);
  CHECK(r.decision == Decision::Open && r.matched.targetId == 3);

  // Deliberate difference: firmware has no time-profile definitions yet and
  // fails closed (Python opens Olga at 10:00 via profile 2).
  CHECK(run(olga, true, now).decision == Decision::DenyNotAtThisTime);

  // Time unknown: cards with an expiry are refused, permanent cards still work.
  CHECK(run(olga, false, 0).decision == Decision::DenyTimeUnknown);
  CHECK(run(ben, false, 0).decision == Decision::DenyTimeUnknown);
  CHECK(run(sara, false, 0).decision == Decision::Open);

  // Malformed / unknown format
  Card bad = sara;
  bad.file0[0] = 0;
  CHECK(run(bad, true, now).decision == Decision::DenyUnknownFormat);
  bad = sara;
  bad.file0[1] = 65;
  CardHeader hb;
  parseHeader(bad.file0.data(), 16, hb);
  CHECK(checkHeader(hb, kLock, true, now) == Decision::DenyMalformed);

  // Unknown entry types are ignored
  Card odd = sara;
  odd.file1[4] = 0x7F;  // "zone 4" entry becomes unknown type
  CHECK(run(odd, true, now).decision == Decision::DenyNoRight);

  // Y2038-safe clock helper
  UtcDateTime t = toUtc(0);
  CHECK(t.year == 1970 && t.month == 1 && t.day == 1);
  t = toUtc(2147483648u);  // first second after signed 32-bit overflow
  CHECK(t.year == 2038 && t.month == 1 && t.day == 19 && t.hour == 3 && t.minute == 14 && t.second == 8);
  t = toUtc(0xFFFFFFFFu);
  CHECK(t.year == 2106 && t.month == 2 && t.day == 7 && t.hour == 6 && t.minute == 28 && t.second == 15);
  t = toUtc(1795510800u);
  CHECK(t.year == 2026 && t.month == 11 && t.day == 24 && t.hour == 9);

  if (failures == 0) std::printf("access_decision host tests: all passed\n");
  return failures == 0 ? 0 : 1;
}
